from pathlib import Path
import re

p=Path('src/AppFinal.tsx')
s=p.read_text()

s=s.replace("{key:'exams',label:'Denemeler',icon:BookOpen,subs:['Deneme Seç','Takvimim','Cevap Anahtarları']}","{key:'exams',label:'Denemeler',icon:BookOpen,subs:['Deneme Kataloğu','Takvimim','Cevap Anahtarları']}",1)

new_plan = r'''function PlanBuilder({boot,user}:{boot:Bootstrap;user:User}){const activeSeason=boot.seasons.find(s=>s.is_active)?.id||boot.seasons[0]?.id||'',[inst,setInst]=useState(user.role==='KURUM'?user.institution_id||'':boot.institutions[0]?.id||''),[season,setSeason]=useState(activeSeason),[grade,setGrade]=useState(''),[publisher,setPublisher]=useState(''),[month,setMonth]=useState(''),[q,setQ]=useState(''),[selected,setSelected]=useState<Record<string,any>>({}),[qtyModal,setQtyModal]=useState(false),[msg,setMsg]=useState('');const institution=boot.institutions.find(i=>i.id===inst);const allowedGrades=boot.grades.filter(g=>(institution?.grade_level_ids||[]).includes(g.id));useEffect(()=>{if(grade&&!allowedGrades.some(g=>g.id===grade))setGrade('')},[inst,boot.grades.length]);const exams=useAsync(()=>inst?api(`/api/exams?season_id=${season}&active=1${grade?`&grade_level_id=${grade}`:''}${publisher?`&publisher_id=${publisher}`:''}${month?`&month=${month}`:''}${q?`&q=${encodeURIComponent(q)}`:''}`):Promise.resolve({items:[]}),[inst,season,grade,publisher,month,q]);const plans=useAsync(()=>inst?api(`/api/plans?institution_id=${inst}&season_id=${season}`):Promise.resolve({items:[]}),[inst,season]);const existing=new Set(((plans.data as any)?.items||[]).map((x:any)=>x.exam_id));const examItems=((exams.data as any)?.items||[]).filter((x:any)=>allowedGrades.some(g=>g.id===x.grade_level_id));const choose=(x:any)=>setSelected(s=>s[x.id]?Object.fromEntries(Object.entries(s).filter(([k])=>k!==x.id)):{...s,[x.id]:x});const reset=()=>{setGrade('');setPublisher('');setMonth('');setQ('')};const save=async(items:any[])=>{const d=await api('/api/plans',{method:'POST',body:JSON.stringify({institution_id:inst,season_id:season,items})});setMsg(`${d.added} sınav planlandı ve sipariş bekleyenlere eklendi.`);setSelected({});setQtyModal(false);plans.reload()};const selectedItems=Object.values(selected);return <><div className="info-box"><b>{user.role==='KURUM'?'Kurum Deneme Kataloğu':'Kurum İçin Deneme Seçimi'}</b><div>Sezon, sınıf, yayınevi, ay veya arama ile denemeleri hızla süzün. İstediğiniz denemeleri seçip adetlerini tek seferde girerek plan ve takvimi oluşturabilirsiniz.</div></div><Toolbar>{user.role!=='KURUM'&&<select title="Kurum" value={inst} onChange={e=>{setInst(e.target.value);setSelected({});setGrade('')}}>{boot.institutions.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select>}<select title="Sezon" value={season} onChange={e=>{setSeason(e.target.value);setSelected({})}}>{boot.seasons.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><select title="Sınıf" value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{allowedGrades.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select><select title="Durum" value="1" disabled><option value="1">Aktif</option></select><select title="Yayınevi" value={publisher} onChange={e=>setPublisher(e.target.value)}><option value="">Tüm yayınevleri</option>{boot.publishers.filter(p=>p.is_active!==0).map(p=><option key={p.id} value={p.id}>{p.short_name||p.name}</option>)}</select><select title="Ay" value={month} onChange={e=>setMonth(e.target.value)}><option value="">Tüm aylar</option>{MONTHS.map(m=><option key={m.v} value={m.v}>{m.n}</option>)}</select><SearchBox value={q} set={setQ}/><button className="btn" onClick={reset}><RefreshCw size={15}/> Filtreleri Temizle</button><div className="spacer"/><div className="selection-count">Gösterilen <b>{examItems.length}</b> · Seçili <b>{selectedItems.length}</b></div></Toolbar>{!allowedGrades.length?<Empty text="Bu kurum için aktif sınıf düzeyi tanımlanmamış."/>:exams.loading?<Loading/>:<DataTable cols={['Seç','Tarih','Sınıf','Tür','Zorluk','Yayınevi','Deneme','Kod','Son Sipariş','Satış','Durum']} rows={examItems.map((x:any)=>{const has=existing.has(x.id),picked=!!selected[x.id];return [<label key="c" className={`catalog-select-box ${has?'disabled':''}`} title={has?'Bu deneme zaten planlandı':'Plan için seç'}><input type="checkbox" disabled={has} checked={has||picked} onChange={()=>choose(x)}/><span>{has?'Planlandı':picked?'Seçildi':'Seç'}</span></label>,fmtShort(x.application_start_date),x.grade_name,x.exam_type==='DERS_SINAVI'?`Ders · ${x.subject||'—'}`:(x.exam_type||'Deneme'),x.difficulty_level||'—',x.publisher_short||x.publisher_name,x.name,x.code,fmtDate(x.last_order_date),fmtMoney(x.default_sale_price),<Badge key="b" text={has?'Planlandı':'Aktif'} tone={has?'good':'info'}/>]})}/>} {!exams.loading&&allowedGrades.length>0&&!examItems.length&&<Empty text="Bu filtrelere uygun aktif deneme bulunamadı. Filtreleri temizleyerek tekrar deneyin."/>}{msg&&<div className="success-box"><CheckCircle2 size={18}/>{msg}</div>}<div className="sticky-action"><span>{selectedItems.length} sınav seçildi</span><button className="btn primary" disabled={!selectedItems.length} onClick={()=>setQtyModal(true)}><CalendarDays size={16}/> Seçimleri Onayla</button></div>{qtyModal&&<QuantityModal boot={boot} exams={selectedItems} close={()=>setQtyModal(false)} save={save}/>} {user.role==='KURUM'&&<InstitutionPendingOrders refreshKey={msg}/>}</>}'''

pat=r"function PlanBuilder\(\{boot,user\}:\{boot:Bootstrap;user:User\}\)\{.*?\}\nfunction InstitutionPendingOrders"
m=re.search(pat,s,re.S)
if not m:
    raise SystemExit('PlanBuilder anchor not found')
s=s[:m.start()]+new_plan+'\nfunction InstitutionPendingOrders'+s[m.end():]

# Make the catalog friendlier for every role without changing admin actions.
pat2=r"(function ExamCatalog\(\{boot,canEdit\}:\{boot:Bootstrap;canEdit:boolean\}\)\{.*?const exportXlsx=async\(\)=>\{.*?\};return )<><Toolbar>"
m2=re.search(pat2,s,re.S)
if not m2:
    raise SystemExit('ExamCatalog return anchor not found')
intro='''<><div className="info-box"><b>Deneme Kataloğu</b><div>Sezon, sınıf, durum, yayınevi, ay ve arama filtrelerini birlikte kullanabilirsiniz. Filtreler tüm kullanıcı rollerinde aynı yerde çalışır; işlem butonları kullanıcı yetkisine göre gösterilir.</div></div><Toolbar>'''
s=s[:m2.start()]+m2.group(1)+intro+s[m2.end():]

old='<SearchBox value={q} set={setQ}/><div className="spacer"/>'
new='<SearchBox value={q} set={setQ}/><button className="btn" onClick={()=>{setGrade(\'\');setActive(\'1\');setPublisher(\'\');setMonth(\'\');setQ(\'\')}}><RefreshCw size={15}/> Filtreleri Temizle</button><span className="selection-count">Gösterilen <b>{items.length}</b></span><div className="spacer"/>'
# Replace only the first instance after ExamCatalog begins.
pos=s.index('function ExamCatalog')
idx=s.find(old,pos)
if idx<0:
    raise SystemExit('ExamCatalog searchbox anchor not found')
s=s[:idx]+new+s[idx+len(old):]

p.write_text(s)
